rows=[]
for i,line in enumerate(RAW.strip().splitlines()):
 topic,lane,asset,narration,motion=line.split('|')
 runner={'manim':'Show Tell isometric arrangement','capture':'Manim conceptual reconstruction','code':'GodotDevWorkbench source-backed editor view','shell':'BrowserCapture of terminal output'}[lane]
 why={'manim':'The spatial or temporal transformation is the claim; a physical-object metaphor would obscure its exact geometry.','capture':'A real captured artifact exists and directly supports the claim; reconstructed output would add no evidence.','code':'Exact runnable source is the teaching target; a full editor layout would reduce usable code size.','shell':'Verbatim recorded output establishes the observation and keeps its evidence limits visible.'}[lane]
 rows.append({'id':f'B{i+1:02}','act':i//9,'topic':topic,'lane':lane,'asset':asset,'narration':narration,'motion':motion,'runner_up':runner,'why':why})
assert len(rows)==54
rows.insert(next(i for i,x in enumerate(rows) if x['id']=='B47'),{'id': 'B46A', 'act': 5, 'topic': 'Backend migration details', 'lane': 'code', 'asset': 'migration_excerpt', 'narration': 'The four point seven migration notes change Jolt world-boundary distance signs, soft-body mass and stiffness behavior, and area overlap reporting for soft bodies. These are backend-specific migration checks; they do not rewrite the two D platformer.', 'motion': 'Highlight four short quoted fragments from the already retrieved official migration record.', 'runner_up': 'Live BrowserCapture focused on the migration paragraphs', 'why': 'A later focus recapture received HTTP 429. Use the successfully retrieved official text as a clearly labeled excerpt; do not show an unrelated page section as if it contained these claims.'})
(R/'content.json').write_text(json.dumps({'title':TITLE,'acts':ACTS,'body':rows},indent=2)+'\n')
print(len(rows),'body beats')
